{"path": "wordy.py", "content": """"Parse and evaluate simple math word problems."""

OPERATIONS = {
    "plus": lambda x, y: x + y,
    "minus": lambda x, y: x - y,
    "multiplied": lambda x, y: x * y,
    "divided": lambda x, y: _divide(x, y),
}


def _divide(x, y):
    if y == 0:
        raise ValueError("syntax error")
    quotient = abs(x) // abs(y)
    return quotient if (x < 0) == (y < 0) else -quotient


def _to_int(token):
    try:
        return int(token)
    except ValueError:
        return None


def answer(question):
    question = question.strip()
    prefix = "What is"
    if not question.startswith(prefix):
        raise ValueError("unknown operation")
    body = question[len(prefix):].strip().rstrip("?").strip()
    body = body.replace("multiplied by", "multiplied").replace("divided by", "divided")
    tokens = body.split()
    if not tokens:
        raise ValueError("syntax error")

    result = None
    operation = None
    for index, token in enumerate(tokens):
        number = _to_int(token)
        if index % 2 == 0:
            # Expect a number here.
            if number is None:
                if token in OPERATIONS:
                    raise ValueError("syntax error")
                raise ValueError("unknown operation")
            result = number if operation is None else operation(result, number)
        else:
            # Expect an operation here.
            if number is not None:
                raise ValueError("syntax error")
            if token not in OPERATIONS:
                raise ValueError("unknown operation")
            operation = OPERATIONS[token]

    if len(tokens) % 2 == 0:
        raise ValueError("syntax error")
    return result
